/* lessons-L7.js — lessons D11, E1, E2, E3 (statistics for the paper + what the named pathways do).
   Written by one content author (scope L7). Each lesson only ADDS to window.LESSON_CONTENT.
   All worked examples use made-up numbers and are labelled as background. */
(window.LESSON_CONTENT = window.LESSON_CONTENT || []).push(

/* ============================================================================================== E1 */
{
  id: 'E1',
  body: [
    { k: 'h', text: 'The problem: one number means little' },
    { k: 'bgnd', html: `<p>A lab result says: "the cells made 50 units of a molecule." Is that a lot? You cannot tell until you know what to compare it with, and how far you can trust it. This lesson gives you the everyday tools biologists use for that: <b>fold change</b>, <b>log2</b>, <b>replicates</b>, <b>mean, median and SD</b>, and <b>error bars</b>.</p>` },

    { k: 'h', text: 'Fold change: how many times bigger or smaller' },
    { k: 'bgnd', html: `<p>A <b>fold change</b> (FC) is the new value divided by the old (or control) value. Going from 50 to 150 gives FC = 150 ÷ 50 = 3, a 3-fold increase. Going from 50 to 25 gives FC = 25 ÷ 50 = 0.5, a halving.</p><p>There is a catch. Increases run from 1 up to very large numbers, but decreases are squeezed between 1 and 0. So a doubling (2) and a halving (0.5) do not look like opposites, even though they are.</p>` },

    { k: 'h', text: 'log2: doubling and halving become mirror images' },
    { k: 'bgnd', html: `<p>A <b>logarithm</b> fixes this. <b>log2</b> asks: how many times did the value double? One doubling is +1, two doublings +2; one halving is −1, two halvings −2; no change is 0. The <b>log2 fold change</b> (log2FC) is therefore symmetric around 0. (<b>log10</b> works the same way with factors of ten: the log10 of 1,000 is 3.)</p>` },
    { k: 'svg', caption: 'Each step to the right doubles the value (+1); each step to the left halves it (−1). 0 means no change.',
      svg: `<svg viewBox="0 0 480 236" role="img" aria-label="A number line from log2 fold change minus 3 to plus 3. Each step to the right doubles the value and each step to the left halves it, so a fold change of 1/8, 1/4, 1/2, 1, 2, 4, 8 sits at minus 3 to plus 3."><text x="240" y="24" class="mid b">fold change = new ÷ old</text><text x="60" y="56" class="mid">1/8</text><text x="120" y="56" class="mid">1/4</text><text x="180" y="56" class="mid">1/2</text><text x="240" y="56" class="mid b">1</text><text x="300" y="56" class="mid">2</text><text x="360" y="56" class="mid">4</text><text x="420" y="56" class="mid">8</text><path d="M28 84 H240" class="ln thick s-blue"/><path d="M240 84 H452" class="ln thick s-orange"/><path d="M60 74 V94" class="ln"/><path d="M120 74 V94" class="ln"/><path d="M180 74 V94" class="ln"/><path d="M240 74 V94" class="ln"/><path d="M300 74 V94" class="ln"/><path d="M360 74 V94" class="ln"/><path d="M420 74 V94" class="ln"/><circle cx="240" cy="84" r="6" class="solid-text"/><text x="60" y="122" class="mid b t-blue">−3</text><text x="120" y="122" class="mid b t-blue">−2</text><text x="180" y="122" class="mid b t-blue">−1</text><text x="240" y="122" class="mid b">0</text><text x="300" y="122" class="mid b t-orange">+1</text><text x="360" y="122" class="mid b t-orange">+2</text><text x="420" y="122" class="mid b t-orange">+3</text><text x="240" y="150" class="mid m s">log2 fold change: 0 = no change, each step = one doubling</text><path d="M232 188 H62" class="arrow s-blue"/><text x="147" y="212" class="mid s t-blue b">smaller: halves each step</text><path d="M248 188 H418" class="arrow s-orange"/><text x="333" y="212" class="mid s t-orange b">bigger: doubles each step</text></svg>` },
    { k: 'worked', html: `<p><b>Worked example (made-up numbers).</b> A gene reads 80 units in control cells and 20 in treated cells.<br>1. Fold change = treated ÷ control = 20 ÷ 80 = 0.25.<br>2. How many halvings is that? 80 → 40 → 20: two.<br>3. So log2FC = −2.<br>To go back, FC = 2<sup>log2FC</sup>. For example, log2FC = −1.5 means FC = 2<sup>−1.5</sup> = 0.35, about 2.8 times lower.</p>` },

    { k: 'h', text: 'Replicates: biological versus technical' },
    { k: 'bgnd', html: `<p>One measurement can be a fluke, so experiments are repeated. A <b>biological replicate</b> starts from an independent sample, for example a separate dish of cells that is grown, treated and measured on its own. A <b>technical replicate</b> measures the same sample again. Biological replicates show how much the biology and the whole procedure vary; technical replicates show only the noise of the measuring step.</p><p>The number of independent replicates behind a result is its <b>sample size, n</b>. In lab work n = 3 or 4 is common, which means every mean and SD is only a rough estimate.</p>` },
    { k: 'memory', html: `<p><b>Analogy:</b> baking three separate loaves tells you how much your recipe varies (biological). Tasting three slices of one loaf tells you only how consistent your tasting is (technical). Three slices of one loaf is still n = 1 loaf.</p>` },

    { k: 'h', text: 'Mean, median and standard deviation' },
    { k: 'bgnd', html: `<p>The <b>mean</b> (average) adds the values and divides by how many there are. The <b>median</b> is the middle value once they are lined up in order. The <b>standard deviation (SD)</b> says how far values typically sit from the mean: a small SD means the replicates agree, a large one means they scatter.</p>` },
    { k: 'worked', html: `<p><b>Worked example (made-up numbers).</b> Five counts: 10, 11, 12, 12, 40.<br>Mean = (10 + 11 + 12 + 12 + 40) ÷ 5 = 85 ÷ 5 = 17.<br>Median: the middle (3rd) of the five values in order is 12.<br>The single odd value (40) drags the mean up to 17 but barely moves the median. That is why medians are popular for noisy data.</p><p>Now the SD of three replicates 2, 4 and 6:<br>1. Mean = 4.<br>2. Distances from the mean: −2, 0, +2.<br>3. Square them: 4, 0, 4. Add them up: 8.<br>4. Divide by n − 1 = 2: 4. (Using n − 1 rather than n is the usual correction for a small sample.)<br>5. Take the square root: SD = 2.</p>` },

    { k: 'h', text: 'Error bars: always ask what they show' },
    { k: 'bgnd', html: `<p><b>Error bars</b> are the whiskers on a dot or bar. In the picture, each dot is one replicate, the line is the mean, and the whisker runs from mean − SD to mean + SD. But the same-looking whisker can also mean the standard error (always shorter than the SD), a confidence interval, or the noise of technical replicates. So a figure legend <b>must say which kind it is</b>, and what n is. If it does not, you cannot interpret the bars.</p><p>How far apart two groups sit, compared with their whiskers, is only a first impression. Deciding whether a difference is real needs a statistical test (lessons E2 and E3).</p>` },
    { k: 'svg', caption: 'Two groups of three replicates (made-up numbers). Both groups have SD = 2; the means are 10 and 6.',
      svg: `<svg viewBox="0 0 480 290" role="img" aria-label="Dot plot of two groups of three replicates. Control dots at 8, 10 and 12 have mean 10 and a whisker from 8 to 12. Treated dots at 4, 6 and 8 have mean 6 and a whisker from 4 to 8. The whisker is the mean plus and minus one standard deviation, which is 2 in both groups."><path d="M44 30 V230 H466" class="ln thin m"/><path d="M38 230 H44" class="ln thin m"/><text x="32" y="235" class="end s m">0</text><path d="M38 173 H44" class="ln thin m"/><text x="32" y="178" class="end s m">4</text><path d="M38 116 H44" class="ln thin m"/><text x="32" y="121" class="end s m">8</text><path d="M38 59 H44" class="ln thin m"/><text x="32" y="64" class="end s m">12</text><text x="44" y="22" class="s m">measured value</text><circle cx="150" cy="116" r="6" class="solid-blue"/><circle cx="180" cy="87" r="6" class="solid-blue"/><circle cx="210" cy="59" r="6" class="solid-blue"/><path d="M132 87 H228" class="ln thick"/><path d="M256 116 V59 M248 116 H264 M248 59 H264" class="ln s-red"/><text x="270" y="92" class="s t-red b">SD = 2</text><circle cx="310" cy="173" r="6" class="solid-orange"/><circle cx="340" cy="144" r="6" class="solid-orange"/><circle cx="370" cy="116" r="6" class="solid-orange"/><path d="M292 144 H388" class="ln thick"/><path d="M416 173 V116 M408 173 H424 M408 116 H424" class="ln s-red"/><text x="430" y="149" class="s t-red b">SD = 2</text><text x="180" y="252" class="mid b">control</text><text x="340" y="252" class="mid b">treated</text><text x="126" y="92" class="end s b">mean = 10</text><text x="286" y="149" class="end s b">mean = 6</text><text x="240" y="278" class="mid s m">dot = one replicate · line = mean · whisker = mean ± SD</text></svg>` },

    { k: 'h', text: 'Percentiles, and the software' },
    { k: 'bgnd', html: `<p>A <b>percentile</b> is a position in the ordered list: 10% of the values lie below the 10th percentile, 90% below the 90th, and the 50th percentile is the median. The ratio of the 90th to the 10th percentile is a quick, outlier-proof way to say how spread out a set of values is.</p><p>The authors ran their statistics and drew their plots with <b>GraphPad Prism</b> (a point-and-click program) and <b>R</b> (a programming language; add-on packages such as ggplot2 draw the plots). Heads-up: a capital R printed on a plot next to a number (as in "R=0.66") is not this software. It is a statistic you will meet in lesson E2.</p>` },

    { k: 'h', text: 'How this paper uses these ideas' },
    { k: 'paper', ref: 'm-hits-p2', quote: 'Gene level (replicate specific) log2FC was derived as the median of log2FC values from all pgRNAs (filtered as described) targeting the same genomic region' },
    { k: 'plain', source: ['m-hits-p2', 'res-pipeline-p4'], html: `<p>Every target is attacked by ten guide pairs (pgRNAs). Each guide pair gets its own log2 fold change (treatment sample ÷ control sample, on the log2 scale). To get one number per target, the authors took the <b>median</b> of the guide-level values.</p>` },
    { k: 'bgnd', html: `<p>Why a median? The paragraph gives no reason, but one is natural: if one of the ten guide pairs works badly, a median ignores it, while a mean would be dragged toward it.</p>` },
    { k: 'paper', ref: 'fig5F', quote: 'The error bars represent the variability of technical replicates, while the biological replicates are indicated on the bottom (n = 4 biological replicates; n > 3 technical replicates; error bars: SD …' },
    { k: 'plain', source: ['fig5F', 'fig5C', 'fig3F'], html: `<p>Legends are where a paper tells you what its error bars are. Figure 5F (organoids grown from one patient-derived xenograft) separates the two kinds of replicate: n = 4 biological replicates and n > 3 technical replicates, with bars showing the spread (SD) of the technical ones. Figure 5C says "n = 4 biological replicates; error bars: SD", and Figure 3F says "mean ± SD from three independent biological replicates".</p>` },
    { k: 'flag', source: ['fig1F'], html: `<p>Not every legend is this careful. The legend of Figure 1F is a single sentence about what was measured. The picture shows error bars and "n=3", but the legend never says what the bars are (SD? standard error?). For those bars the kind is simply unknown.</p>` },
    { k: 'paper', ref: 'res-pipeline-p4', quote: 'coverage (90th to 10th percentile count ratios: 4.6-fold)' },
    { k: 'plain', source: ['res-pipeline-p4'], html: `<p>After the guide pairs were put into the plasmid, the authors checked how evenly each one was represented. They report a 90th-to-10th percentile count ratio of 4.6-fold: the guide pair at the 90th percentile of the counts was about 4.6 times as abundant as the one at the 10th percentile. A perfectly even mix would give a ratio of exactly one.</p>` },
    { k: 'paper', ref: 'm-quant-p1', quote: 'Statistical analysis, quantification and visualisation was performed using Graphpad Prism … R Statistical Software' },
    { k: 'plain', source: ['m-quant-p1'], html: `<p>The statistics methods name GraphPad Prism and R, plus a long list of R packages (ggplot2 among them), as the tools for the statistics and the plots.</p>` },
  ],
  appears: [
    { ref: 'm-hits-p2', note: 'Gene-level log2 fold change is the median of the guide-level values; Z-scaling is described here too.' },
    { ref: 'fig5F', note: 'The legend separates biological from technical replicates and says the error bars are SD.' },
    { ref: 'fig5C', note: '"n = 4 biological replicates; error bars: SD": the kind of legend you want.' },
    { ref: 'fig1F', note: 'A legend that does not say what its error bars are.' },
    { ref: 'res-pipeline-p4', note: 'A percentile ratio (90th to 10th: 4.6-fold) used as an evenness check.' },
    { ref: 'm-quant-p1', note: 'GraphPad Prism and R, with the list of R packages.' },
  ],
  checks: [
    { q: `Control cells show 40 units of an RNA and treated cells show 10 units. What is the log2 fold change (treated ÷ control)?`,
      options: [
        { t: `−2`, ok: true, why: `10 ÷ 40 = 0.25, and 40 → 20 → 10 is two halvings, so the log2 fold change is −2.` },
        { t: `+2`, ok: false, why: `The sign is wrong. The treated value is lower, so the log2 fold change must be negative.` },
        { t: `−0.25`, ok: false, why: `0.25 is the fold change itself. Its log2 counts halvings, which gives −2.` },
        { t: `−4`, ok: false, why: `40 ÷ 10 = 4 is the fold change in the other direction. The log2 of 4 is 2, and the change here is downward, so the answer is −2.` },
      ], bg: true },
    { q: `Which setup gives you three <b>biological</b> replicates?`,
      options: [
        { t: `Three separately grown dishes of cells, each treated and measured on its own`, ok: true, why: `Right: independent samples show how much the biology and the whole procedure vary.` },
        { t: `One dish of cells, measured three times`, ok: false, why: `Re-measuring one sample gives technical replicates. They show measuring noise only, so n is still one.` },
        { t: `One tube of RNA split into three tubes for the same measurement`, ok: false, why: `Splitting one sample is still technical replication: all three tubes share the same biology.` },
        { t: `One photograph of a dish, counted three times`, ok: false, why: `Counting the same photograph again measures your counting, not the cells.` },
      ], bg: true },
    { q: `Counts: 6, 7, 8, 8, 31. Which summary describes a typical value best?`,
      options: [
        { t: `The median, 8, because the odd value 31 hardly affects it`, ok: true, why: `Right: the median is the middle value in order, so one extreme value cannot drag it away.` },
        { t: `The mean, 12, because it uses every value`, ok: false, why: `Using every value is exactly the problem here: 31 pulls the mean up to 12, which is higher than four of the five counts.` },
        { t: `The mean and the median are the same here`, ok: false, why: `They are 12 and 8. They only match for evenly balanced data.` },
        { t: `The median is 7, the second value`, ok: false, why: `The median is the middle (3rd) of the five values in order, which is 8.` },
      ], bg: true },
    { q: `In Figure 5F, what does "n = 4" count?`,
      options: [
        { t: `Biological replicates (independent replicates of the organoids)`, ok: true, why: `Right: the legend says "n = 4 biological replicates", and separately "n > 3 technical replicates".` },
        { t: `Technical replicates (repeat measurements of one sample)`, ok: false, why: `The technical replicates are the separate "n > 3" in the legend, and the error bars show their spread.` },
        { t: `Four patients`, ok: false, why: `The organoids were grown from a single patient-derived xenograft, so there is one source, not four patients.` },
        { t: `Four drug doses`, ok: false, why: `The legend names no doses here. The n counts replicates.` },
      ], source: ['fig5F'] },
    { q: `Figure 5C's legend says "error bars: SD". Figure 1F's legend does not say what its error bars are. What follows?`,
      options: [
        { t: `Figure 5C's bars are SDs; for Figure 1F the kind of error bar is unknown`, ok: true, why: `Right: only a legend can tell you. Here one does and one does not.` },
        { t: `Both are surely SDs, because that is the usual choice`, ok: false, why: `SD is common, but standard errors and confidence intervals are common too. Without a statement you cannot assume.` },
        { t: `Figure 1F has no error bars`, ok: false, why: `The picture does show error bars (and "n=3"). Only the legend is silent about them.` },
        { t: `It does not matter which kind they are`, ok: false, why: `It matters: for the same data a standard error bar is shorter than an SD bar, so the same picture can look more or less convincing.` },
      ], source: ['fig5C', 'fig1F'] },
  ],
},

/* ============================================================================================== E2 */
{
  id: 'E2',
  body: [
    { k: 'h', text: 'The problem: "same" and "different" need numbers' },
    { k: 'bgnd', html: `<p>Two replicates of an experiment should agree. Two screens in different cell lines might agree. How do you put a number on "agree"? And when a figure prints <b>P &lt; 2.2e-16</b>, what is it claiming? This lesson explains <b>correlation</b> (do two measurements move together?), the <b>Z-score</b> (how unusual is one value?) and the <b>p-value</b> (could chance explain this?).</p>` },

    { k: 'h', text: 'Correlation: do two measurements rise and fall together?' },
    { k: 'bgnd', html: `<p>Measure two things on the same items, say the result of replicate 1 and of replicate 2 for every gene, and draw one dot per gene. If the dots form a rising band, the two are <b>correlated</b>: genes that score high in one replicate score high in the other. The <b>Pearson correlation</b> coefficient, r (written R in many figures), puts this on a scale: +1 is a perfect rising straight line, 0 is no straight-line pattern, −1 is a perfect falling line. A falling band is an <b>anti-correlation</b>. The <b>regression line</b> (trendline) is the straight line that fits the dots best.</p>` },
    { k: 'svg', caption: 'Left: dots rise together (r = +0.9). Middle: no pattern (r ≈ 0). Right: one goes up as the other goes down (anti-correlation, r = −0.9).',
      svg: `<svg viewBox="0 0 480 232" role="img" aria-label="Three small dot plots. Left: dots rise from lower left to upper right, correlation about plus 0.9. Middle: dots form a shapeless cloud, correlation about 0. Right: dots fall from upper left to lower right, correlation about minus 0.9, called anti-correlation."><g transform="translate(12 14)"><path d="M0 0 V140 H140" class="ln thin m"/><circle cx="10" cy="107" r="4.5" class="solid-blue"/><circle cx="21" cy="116" r="4.5" class="solid-blue"/><circle cx="31" cy="117" r="4.5" class="solid-blue"/><circle cx="41" cy="82" r="4.5" class="solid-blue"/><circle cx="49" cy="97" r="4.5" class="solid-blue"/><circle cx="56" cy="78" r="4.5" class="solid-blue"/><circle cx="66" cy="71" r="4.5" class="solid-blue"/><circle cx="72" cy="71" r="4.5" class="solid-blue"/><circle cx="82" cy="73" r="4.5" class="solid-blue"/><circle cx="88" cy="75" r="4.5" class="solid-blue"/><circle cx="99" cy="43" r="4.5" class="solid-blue"/><circle cx="112" cy="28" r="4.5" class="solid-blue"/><circle cx="116" cy="55" r="4.5" class="solid-blue"/><circle cx="125" cy="53" r="4.5" class="solid-blue"/><line x1="7" y1="117" x2="133" y2="34" class="ln thick s-orange"/></g><text x="82" y="186" class="mid b">r = +0.9</text><text x="82" y="206" class="mid s">rise together</text><g transform="translate(170 14)"><path d="M0 0 V140 H140" class="ln thin m"/><circle cx="10" cy="91" r="4.5" class="solid-gray"/><circle cx="21" cy="43" r="4.5" class="solid-gray"/><circle cx="28" cy="53" r="4.5" class="solid-gray"/><circle cx="36" cy="49" r="4.5" class="solid-gray"/><circle cx="51" cy="57" r="4.5" class="solid-gray"/><circle cx="56" cy="119" r="4.5" class="solid-gray"/><circle cx="69" cy="80" r="4.5" class="solid-gray"/><circle cx="74" cy="119" r="4.5" class="solid-gray"/><circle cx="84" cy="103" r="4.5" class="solid-gray"/><circle cx="88" cy="47" r="4.5" class="solid-gray"/><circle cx="102" cy="123" r="4.5" class="solid-gray"/><circle cx="110" cy="40" r="4.5" class="solid-gray"/><circle cx="121" cy="62" r="4.5" class="solid-gray"/><circle cx="124" cy="43" r="4.5" class="solid-gray"/><line x1="7" y1="73" x2="133" y2="74" class="ln thick s-orange"/></g><text x="240" y="186" class="mid b">r ≈ 0</text><text x="240" y="206" class="mid s">no straight-line pattern</text><g transform="translate(328 14)"><path d="M0 0 V140 H140" class="ln thin m"/><circle cx="17" cy="29" r="4.5" class="solid-purple"/><circle cx="24" cy="16" r="4.5" class="solid-purple"/><circle cx="33" cy="15" r="4.5" class="solid-purple"/><circle cx="42" cy="42" r="4.5" class="solid-purple"/><circle cx="50" cy="54" r="4.5" class="solid-purple"/><circle cx="58" cy="66" r="4.5" class="solid-purple"/><circle cx="68" cy="72" r="4.5" class="solid-purple"/><circle cx="77" cy="91" r="4.5" class="solid-purple"/><circle cx="80" cy="100" r="4.5" class="solid-purple"/><circle cx="93" cy="85" r="4.5" class="solid-purple"/><circle cx="104" cy="98" r="4.5" class="solid-purple"/><circle cx="106" cy="82" r="4.5" class="solid-purple"/><circle cx="121" cy="111" r="4.5" class="solid-purple"/><circle cx="125" cy="90" r="4.5" class="solid-purple"/><line x1="7" y1="16" x2="133" y2="118" class="ln thick s-orange"/></g><text x="398" y="186" class="mid b">r = −0.9</text><text x="398" y="206" class="mid s">one up, the other down</text><text x="240" y="226" class="mid s m">each dot = one gene · orange line = regression line (trendline)</text></svg>` },
    { k: 'bgnd', html: `<p><b>What r says, and what it does not.</b> It says how tightly the dots hug a straight line, and in which direction. It does <i>not</i> say that one measurement causes the other, how steep the line is (the slope does), or whether the result matters. One extreme dot can inflate or deflate r, and a curved pattern can give r near 0 even when the two clearly belong together. Two replicates can also have r = 0.99 while one reads twice as high as the other: r measures the pattern, not whether the numbers match.</p>` },
    { k: 'worked', html: `<p><b>Worked example (made-up numbers).</b> Four genes, as (replicate 1, replicate 2): (1, 2), (2, 4), (3, 5), (4, 7).<br>1. Means: 2.5 and 4.5.<br>2. Distances from the means. Replicate 1: −1.5, −0.5, +0.5, +1.5. Replicate 2: −2.5, −0.5, +0.5, +2.5.<br>3. Multiply the pairs and add: 3.75 + 0.25 + 0.25 + 3.75 = 8.<br>4. Square the distances and add: 5 for replicate 1, 13 for replicate 2.<br>5. r = 8 ÷ √(5 × 13) = 8 ÷ 8.06 = 0.99.<br>The regression line has slope 8 ÷ 5 = 1.6: each extra unit in replicate 1 goes with about 1.6 more in replicate 2.</p>` },

    { k: 'h', text: 'Z-scores: how unusual is this value?' },
    { k: 'bgnd', html: `<p>A <b>Z-score</b> restates a value as "how many SDs away from the mean of a reference group": z = (value − mean) ÷ SD. Zero is exactly average, +2 is two SDs above, −3 is three SDs below. A Z-score has no units, so very different measurements can share one ruler. For bell-shaped data about 95% of values fall between −2 and +2, so a z beyond ±3 is rare.</p>` },
    { k: 'worked', html: `<p><b>Worked example (made-up numbers).</b> Neutral control guides (the do-nothing reference group) have a mean log2FC of 0.1 and an SD of 0.4. A guide with log2FC = −1.5 has z = (−1.5 − 0.1) ÷ 0.4 = −1.6 ÷ 0.4 = −4. It sits four SDs below what a do-nothing guide typically does.</p>` },

    { k: 'h', text: 'p-values: could chance explain this?' },
    { k: 'bgnd', html: `<p>Every test starts from the <b>null hypothesis</b>: the boring explanation that nothing is going on (no effect, no difference, no relationship). The <b>p-value</b> answers one question: <i>if the null hypothesis were true, how often would chance alone give a result at least as extreme as mine?</i></p>` },
    { k: 'worked', html: `<p><b>Worked example.</b> You flip a coin 10 times and get 9 heads. Of the 1,024 equally likely head/tail sequences (2<sup>10</sup>), 10 have exactly 9 heads and 1 has 10 heads: 11 in all. So p = 11 ÷ 1,024 = 0.011. A fair coin would do this about once in every 93 tries, which is surprising enough to doubt the coin. (This counts only the "too many heads" direction; lesson E3 shows what changes when both directions count.)</p>` },
    { k: 'bgnd', html: `<p><b>What a p-value is not.</b> It is not the probability that the null hypothesis is true, and not the probability that the result is "just chance". It does not measure how big or important an effect is: with very many measurements a tiny difference can give a tiny p. And a large p does not prove there is no effect; it only says the data did not rule chance out. Finally, when thousands of tests are run, some small p-values appear by luck alone (lesson E4).</p><p>Researchers fix a cutoff in advance, usually 0.05. A result with p below it is called <b>statistically significant</b>; the label <b>ns</b> (not significant) marks a comparison that did not get there. "Significant" does not mean "important", and "ns" does not mean "no difference".</p>` },

    { k: 'h', text: 'Scientific notation: reading 5e-4' },
    { k: 'bgnd', html: `<p>Tiny p-values are written in <b>scientific notation</b>. "5e-4" means 5 × 10<sup>−4</sup> = 5 ÷ 10,000 = 0.0005. "1.2 × 10<sup>−7</sup>" (or 1.2e-7) is 0.00000012. The e is not Euler's number; it means "times ten to the power of". The more negative the exponent, the smaller the number, so 5e-4 is far smaller than 0.04. R prints "P &lt; 2.2e-16" for any p-value below that limit: read it as "extremely small", not as an exact value.</p>` },
    { k: 'svg', caption: 'p-values on a log scale: further right means smaller, so more surprising if nothing is going on. The marked values are ones you will meet in the paper.',
      svg: `<svg viewBox="0 0 480 236" role="img" aria-label="A ruler of p-values from 1 on the left to extremely small numbers on the right. The 0.05 line separates not significant (ns) on the left from significant on the right. Marked: 0.05, 5e-4, 4.2e-12 and less than 2.2e-16. Further right means smaller p and stronger evidence against chance."><text x="240" y="22" class="mid b">p-values: further right = smaller = more surprising</text><path d="M30 100 H64" class="ln thick s-gray"/><path d="M64 100 H452" class="ln thick s-green"/><path d="M64 54 V122" class="ln dash s-red"/><text x="70" y="62" class="s t-red b">cutoff 0.05</text><text x="30" y="84" class="s b">ns</text><text x="104" y="90" class="s t-green b">significant</text><circle cx="30" cy="100" r="5" class="solid-text"/><text x="30" y="128" class="s">1</text><circle cx="117" cy="100" r="5" class="solid-blue"/><path d="M117 106 V146" class="ln thin m"/><text x="111" y="164" class="s b">5e-4 = 0.0005</text><circle cx="329" cy="100" r="5" class="solid-purple"/><path d="M329 94 V60" class="ln thin m"/><text x="329" y="52" class="mid s b">4.2e-12</text><circle cx="441" cy="100" r="5" class="solid-orange"/><path d="M441 106 V176" class="ln thin m"/><text x="449" y="196" class="end s b">&lt; 2.2e-16</text><text x="449" y="214" class="end s m">R prints this for “too small to show”</text></svg>` },
    { k: 'memory', html: `<p><b>Analogy:</b> a p-value is a surprise meter. The smaller the number, the more surprised you would be if nothing were going on. The null hypothesis is "innocent until proven guilty": the data must be convincing to overturn it, and "not guilty" (ns) is not the same as "proved innocent".</p>` },

    { k: 'h', text: 'How this paper uses these ideas' },
    { k: 'paper', ref: 'm-hits-p2', quote: 'Log2FC values were also Z score scaled, based on the mean and SD of the neutral control pgRNAs.' },
    { k: 'plain', source: ['m-hits-p2', 'fig2E', 'fig2D'], html: `<p>The authors rescaled each log2 fold change into a Z score, using the mean and SD of the neutral control guides as the reference group. On that scale a Z score of −10 would mean ten SDs below what a do-nothing guide typically does. Figure 2E plots these Z scores for two replicates of the A549 screen and prints "R=0.66, P&lt;2.2e-16": a clear positive correlation, with a P too small to print exactly. Figure 2D prints six R values, from 0.808 to 0.959, comparing the read counts of four samples.</p>` },
    { k: 'paper', ref: 'm-quant-p3', quote: 'For all analyses, p ≤ 0.05 is considered statistically significant unless otherwise specified.' },
    { k: 'plain', source: ['m-quant-p3', 'fig1F'], html: `<p>The paper's cutoff is p ≤ 0.05 "unless otherwise specified". In Figure 1F, seven of the nine guide pairs carry P values between 5e-4 and 0.04, and two are labelled "ns". (The legend does not name the test behind those P values.)</p>` },
    { k: 'paper', ref: 'res-multipheno-p6', quote: 'As expected, these positive selection screens displayed anti-correlation with dropout results in H460 cells, although not in A549 cells, possibly for technical reasons' },
    { k: 'plain', source: ['res-multipheno-p6'], html: `<p>The paper compares two kinds of screen (positive selection screens and dropout screens) and says an anti-correlation between them was expected. It reports the anti-correlation in H460 cells but not in A549 cells, and says the reason may be technical (Figure S2B, a supplementary figure that is not reproduced in this app).</p>` },
    { k: 'plain', source: ['fig2H'], html: `<p>Figure 2H compares the A549 and H460 screens and prints two pairs of numbers: "R=0.4, P=2e-05" in red and "R=0.092, P=0.0035" in black. The legend does not say which dots each pair belongs to.</p>` },
    { k: 'bgnd', html: `<p>Look at the black pair: R = 0.092 is a very weak correlation, yet its P is far below 0.05. P depends on how many dots there are as well as on R, so "significant" is not the same as "strong".</p>` },
  ],
  appears: [
    { ref: 'fig2E', note: 'Two screen replicates plotted as Z scores, with "R=0.66, P<2.2e-16" and a regression line.' },
    { ref: 'fig2D', note: 'A grid of correlations (R) between read counts of four samples.' },
    { ref: 'fig2H', note: 'Two R and P pairs for the A549 versus H460 comparison; a weak but significant correlation.' },
    { ref: 'fig6E', note: 'Fold changes after CHiLL1 knockdown with two ASOs: "R=0.75, P<2.2e-16" and a trendline.' },
    { ref: 'm-quant-p3', note: 'The cutoff: p ≤ 0.05 counts as statistically significant.' },
    { ref: 'res-multipheno-p6', note: 'An expected anti-correlation between two kinds of screen.' },
  ],
  checks: [
    { q: `A plot shows R = −0.8 between two measurements. What does that tell you?`,
      options: [
        { t: `A fairly strong anti-correlation: when one is high, the other tends to be low`, ok: true, why: `Right: the sign gives the direction (negative means opposite) and the size, 0.8 out of a maximum of 1, gives the strength.` },
        { t: `The first measurement causes the second to fall`, ok: false, why: `Correlation never proves cause. A third factor, or chance, could produce the same pattern.` },
        { t: `80% of the dots lie exactly on the line`, ok: false, why: `r is not a percentage of dots. It measures how tightly the whole cloud follows a straight line.` },
        { t: `The relationship is weak, because the number is negative`, ok: false, why: `The sign is only the direction. Strength comes from the size, and 0.8 is close to the maximum.` },
      ], bg: true },
    { q: `Reference values have a mean of 2 and an SD of 0.5. What is the Z-score of the value 3.5?`,
      options: [
        { t: `+3`, ok: true, why: `z = (3.5 − 2) ÷ 0.5 = 1.5 ÷ 0.5 = 3: three SDs above the mean.` },
        { t: `+1.5`, ok: false, why: `That is only the distance from the mean (3.5 − 2). You must still divide by the SD.` },
        { t: `+7`, ok: false, why: `3.5 ÷ 0.5 = 7 forgets to subtract the mean first.` },
        { t: `−3`, ok: false, why: `The value is above the mean, so z is positive.` },
      ], bg: true },
    { q: `A test gives p = 0.03. Which reading is correct?`,
      options: [
        { t: `If nothing were going on, results at least this extreme would turn up about 3% of the time`, ok: true, why: `Right: a p-value is calculated assuming the null hypothesis, and it says how surprising the data would be under it.` },
        { t: `There is a 3% chance that the null hypothesis is true`, ok: false, why: `A p-value is worked out assuming the null hypothesis is true, so it cannot also say how likely that assumption is.` },
        { t: `The result is 97% likely to be real`, ok: false, why: `Subtracting p from 1 does not give the chance that a result is real. That needs more than the p-value.` },
        { t: `The effect is 3% big`, ok: false, why: `A p-value says nothing about how big an effect is.` },
      ], bg: true },
    { q: `In Figure 1F, pgRNA 2 is labelled "P=5e-4" and pgRNA 10 is labelled "P=0.04". Which statement is right?`,
      options: [
        { t: `5e-4 is 0.0005, so pgRNA 2 has the smaller P`, ok: true, why: `Right: e-4 means × 10<sup>−4</sup>, so 5e-4 = 0.0005, about 80 times smaller than 0.04.` },
        { t: `5e-4 means 5 × e<sup>−4</sup> ≈ 0.09, so pgRNA 10 has the smaller P`, ok: false, why: `In P labels the e means "times ten to the power of", not Euler's number. 5e-4 is 0.0005.` },
        { t: `The two are equal, since both are below 0.05`, ok: false, why: `Both pass the cutoff, but 5e-4 is much smaller, so the evidence against "no change" is stronger for pgRNA 2.` },
        { t: `pgRNA 10 is smaller, because 4 is smaller than 5`, ok: false, why: `The exponents decide first. 0.04 is 4e-2, far larger than 5e-4.` },
      ], source: ['fig1F'], derived: ['0.0005', '80', '0.09'] },
    { q: `Figure 2E prints "R=0.66, P<2.2e-16" for two replicates of a screen. What does it tell you?`,
      options: [
        { t: `The replicates show a clear positive correlation, far too strong for chance to explain`, ok: true, why: `Right: R=0.66 is a positive correlation, and P<2.2e-16 is R's way of printing "extremely small".` },
        { t: `The replicates agree perfectly`, ok: false, why: `Perfect agreement would give the maximum possible R. 0.66 is well below it.` },
        { t: `The correlation is not significant`, ok: false, why: `A P below 2.2e-16 is far under the 0.05 cutoff, so the correlation is significant.` },
        { t: `The tiny P proves that one replicate causes the other`, ok: false, why: `Correlation never shows cause. Two replicates of the same screen should agree because the experiment is repeatable.` },
      ], source: ['fig2E', 'm-quant-p3'] },
  ],
},

/* ============================================================================================== E3 */
{
  id: 'E3',
  body: [
    { k: 'h', text: 'The problem: one question per test' },
    { k: 'bgnd', html: `<p>A statistical test answers one narrow question: <i>could chance alone explain this difference or overlap?</i> Different questions need different tests. Ask three things. (1) <b>What am I comparing?</b> Two groups of measurements, three or more groups, or counts in categories? (2) <b>Are the values roughly bell-shaped?</b> (3) <b>Do I care about one direction or both?</b> This lesson walks through the choices, and then shows which ones the paper made.</p>` },

    { k: 'h', text: 'One-tailed or two-tailed?' },
    { k: 'bgnd', html: `<p>If nothing were going on, the results of many repeats of an experiment would pile up in a bell-shaped curve centered on "no difference". The thin ends of the curve are its <b>tails</b>. A <b>two-tailed test</b> counts extreme results in <i>both</i> directions (much higher or much lower than the control) as evidence. A <b>one-tailed test</b> counts only one direction, chosen <i>before</i> looking at the data, for example "knockdown lowers growth".</p><p>For the same data, if the effect points the predicted way, the one-tailed p is half the two-tailed p. That is why the direction must be justified in advance: choosing it after seeing which way the data lean would be cheating, and a one-tailed test is blind to an effect in the other direction.</p>` },
    { k: 'svg', caption: 'The same result (z = 1.8) judged two ways. The shaded areas are the "as extreme as this" chances.',
      svg: `<svg viewBox="0 0 480 372" role="img" aria-label="Two bell curves showing what chance alone would give. Top: a two-tailed test counts both tails beyond z = 1.8 and minus 1.8, 3.6 percent each, 7.2 percent in total. Bottom: a one-tailed test counts only the right tail beyond 1.8, 3.6 percent."><text x="240" y="24" class="mid b">Two-tailed: both tails count</text><path d="M366.0 132 L366.0 114.6 L369.5 116.1 L373.0 117.6 L376.5 118.9 L380.0 120.1 L383.5 121.3 L387.0 122.3 L390.5 123.3 L394.0 124.2 L397.5 125.0 L401.0 125.8 L404.5 126.5 L408.0 127.1 L411.5 127.6 L415.0 128.1 L418.5 128.6 L422.0 129.0 L425.5 129.4 L429.0 129.7 L432.5 130.0 L436.0 130.3 L439.5 130.5 L443.0 130.7 L446.5 130.9 L450.0 131.0 L453.5 131.2 L457.0 131.3 L460.5 131.4 L464.0 131.5 L464.0 132 Z" class="solid-orange" fill-opacity="0.6"/><path d="M16.0 132 L16.0 131.5 L19.5 131.4 L23.0 131.3 L26.5 131.2 L30.0 131.0 L33.5 130.9 L37.0 130.7 L40.5 130.5 L44.0 130.3 L47.5 130.0 L51.0 129.7 L54.5 129.4 L58.0 129.0 L61.5 128.6 L65.0 128.1 L68.5 127.6 L72.0 127.1 L75.5 126.5 L79.0 125.8 L82.5 125.0 L86.0 124.2 L89.5 123.3 L93.0 122.3 L96.5 121.3 L100.0 120.1 L103.5 118.9 L107.0 117.6 L110.5 116.1 L114.0 114.6 L114.0 132 Z" class="solid-orange" fill-opacity="0.6"/><path d="M16.0 131.5 L23.0 131.3 L30.0 131.0 L37.0 130.7 L44.0 130.3 L51.0 129.7 L58.0 129.0 L65.0 128.1 L72.0 127.1 L79.0 125.8 L86.0 124.2 L93.0 122.3 L100.0 120.1 L107.0 117.6 L114.0 114.6 L121.0 111.3 L128.0 107.6 L135.0 103.5 L142.0 99.1 L149.0 94.3 L156.0 89.3 L163.0 84.1 L170.0 78.8 L177.0 73.5 L184.0 68.3 L191.0 63.3 L198.0 58.7 L205.0 54.5 L212.0 51.0 L219.0 48.1 L226.0 46.0 L233.0 44.7 L240.0 44.2 L247.0 44.7 L254.0 46.0 L261.0 48.1 L268.0 51.0 L275.0 54.5 L282.0 58.7 L289.0 63.3 L296.0 68.3 L303.0 73.5 L310.0 78.8 L317.0 84.1 L324.0 89.3 L331.0 94.3 L338.0 99.1 L345.0 103.5 L352.0 107.6 L359.0 111.3 L366.0 114.6 L373.0 117.6 L380.0 120.1 L387.0 122.3 L394.0 124.2 L401.0 125.8 L408.0 127.1 L415.0 128.1 L422.0 129.0 L429.0 129.7 L436.0 130.3 L443.0 130.7 L450.0 131.0 L457.0 131.3 L464.0 131.5" class="ln thick"/><path d="M16 132 H464" class="ln thin m"/><path d="M366 124 V140 M240 128 V136 M114 124 V140" class="ln thin"/><text x="240" y="156" class="mid s">0 (no difference)</text><text x="366" y="156" class="mid s">+1.8</text><text x="114" y="156" class="mid s">−1.8</text><path d="M418.5 92 L401 123" class="ln thin m"/><text x="422" y="86" class="mid s b">3.6%</text><path d="M61.5 92 L79 123" class="ln thin m"/><text x="58" y="86" class="mid s b">3.6%</text><text x="240" y="178" class="mid s">3.6% + 3.6% = 7.2%, so p = 0.072 (ns)</text><text x="240" y="210" class="mid b">One-tailed: only the predicted tail counts</text><path d="M366.0 318 L366.0 300.6 L369.5 302.1 L373.0 303.6 L376.5 304.9 L380.0 306.1 L383.5 307.3 L387.0 308.3 L390.5 309.3 L394.0 310.2 L397.5 311.0 L401.0 311.8 L404.5 312.5 L408.0 313.1 L411.5 313.6 L415.0 314.1 L418.5 314.6 L422.0 315.0 L425.5 315.4 L429.0 315.7 L432.5 316.0 L436.0 316.3 L439.5 316.5 L443.0 316.7 L446.5 316.9 L450.0 317.0 L453.5 317.2 L457.0 317.3 L460.5 317.4 L464.0 317.5 L464.0 318 Z" class="solid-orange" fill-opacity="0.6"/><path d="M16.0 317.5 L23.0 317.3 L30.0 317.0 L37.0 316.7 L44.0 316.3 L51.0 315.7 L58.0 315.0 L65.0 314.1 L72.0 313.1 L79.0 311.8 L86.0 310.2 L93.0 308.3 L100.0 306.1 L107.0 303.6 L114.0 300.6 L121.0 297.3 L128.0 293.6 L135.0 289.5 L142.0 285.1 L149.0 280.3 L156.0 275.3 L163.0 270.1 L170.0 264.8 L177.0 259.5 L184.0 254.3 L191.0 249.3 L198.0 244.7 L205.0 240.5 L212.0 237.0 L219.0 234.1 L226.0 232.0 L233.0 230.7 L240.0 230.2 L247.0 230.7 L254.0 232.0 L261.0 234.1 L268.0 237.0 L275.0 240.5 L282.0 244.7 L289.0 249.3 L296.0 254.3 L303.0 259.5 L310.0 264.8 L317.0 270.1 L324.0 275.3 L331.0 280.3 L338.0 285.1 L345.0 289.5 L352.0 293.6 L359.0 297.3 L366.0 300.6 L373.0 303.6 L380.0 306.1 L387.0 308.3 L394.0 310.2 L401.0 311.8 L408.0 313.1 L415.0 314.1 L422.0 315.0 L429.0 315.7 L436.0 316.3 L443.0 316.7 L450.0 317.0 L457.0 317.3 L464.0 317.5" class="ln thick"/><path d="M16 318 H464" class="ln thin m"/><path d="M366 310 V326 M240 314 V322" class="ln thin"/><text x="240" y="342" class="mid s">0 (no difference)</text><text x="366" y="342" class="mid s">+1.8</text><path d="M418.5 278 L401 309" class="ln thin m"/><text x="422" y="272" class="mid s b">3.6%</text><text x="240" y="364" class="mid s">3.6%, so p = 0.036 (below 0.05)</text></svg>` },
    { k: 'worked', html: `<p><b>Worked example (made-up numbers).</b> A test gives z = 1.8, meaning 1.8 SDs above "no difference". The area of the curve beyond +1.8 is 3.6% (0.036). <i>One-tailed:</i> p = 0.036, below 0.05, "significant". <i>Two-tailed:</i> count both tails, 3.6% + 3.6% = 7.2%, so p = 0.072, "ns". Same data, different verdict, which is why the choice has to be stated and justified. (Real t-tests use a slightly wider curve when n is small, so the exact numbers differ, but the idea is the same.)</p>` },

    { k: 'h', text: `Two group averages: Student's and Welch's t-test` },
    { k: 'bgnd', html: `<p>To compare the <b>means</b> of two groups, use a <b>t-test</b>. It turns the difference between the means into a ratio: t = (difference of the means) ÷ (noise in that difference). A large t, judged against a bell-shaped curve, gives a small p. <b>Student's t-test</b> assumes both groups scatter equally (the same SD) and are roughly bell-shaped. <b>Welch's t-test</b> drops the equal-scatter assumption, so it stays honest when the SDs or the group sizes differ; many statisticians use it as the default.</p>` },
    { k: 'worked', html: `<p><b>Worked example (made-up numbers).</b> Control: 10, 12, 14 (mean 12, SD 2). Treated: 6, 8, 10 (mean 8, SD 2).<br>Difference of the means = 12 − 8 = 4.<br>Noise = √(SD²÷n for each group, added) = √(4/3 + 4/3) = √2.67 = 1.63.<br>t = 4 ÷ 1.63 = 2.45.<br>With 3 + 3 values, a t of 2.45 gives a two-tailed p of about 0.07 ("ns") and a one-tailed p of about 0.035. (The SDs are equal here, so Student's and Welch's tests agree.)</p>` },

    { k: 'h', text: 'Not bell-shaped? Rank tests' },
    { k: 'bgnd', html: `<p>A <b>non-parametric (rank-based) test</b> ignores the actual values and uses only their order. Line up all the values from both groups, give them ranks (1 = smallest), and ask whether one group's ranks tend to be higher. The <b>Wilcoxon</b> rank-sum test and the <b>Mann–Whitney</b> test are two names for this two-group test. Outliers matter little: the biggest value is just "last".</p><p>The <b>Kruskal–Wallis</b> test is the same idea for three or more groups. It gives one global answer ("do the groups differ at all?"). Pairwise follow-up tests, such as Wilcoxon, then show which pairs differ.</p>` },
    { k: 'worked', html: `<p><b>Worked example (made-up numbers).</b> Control: 4, 7, 9. Treated: 10, 15, 30. All six values ranked: 4→1, 7→2, 9→3, 10→4, 15→5, 30→6. The control ranks add up to 1 + 2 + 3 = 6, the treated to 4 + 5 + 6 = 15.<br>How likely is it that the control group gets the three lowest ranks by luck? There are 20 ways to choose which 3 of the 6 ranks go to the control group, and only 1 of them is this extreme: 1/20 = 0.05 one-tailed, or 2/20 = 0.10 two-tailed.<br>Replace 30 by 3,000 and nothing changes. But note: with only 3 values per group, even a perfect split cannot reach p below 0.05 two-tailed. Rank tests need a few more replicates.</p>` },

    { k: 'h', text: `Counting overlaps: hypergeometric and Fisher's exact test` },
    { k: 'bgnd', html: `<p>Sometimes the data are counts, not measurements: how many genes sit on both of two lists, and is that more than luck would give? Picture an urn of N marbles, K of them red. Scoop n marbles without putting any back. The <b>hypergeometric test</b> asks how likely a scoop is to hold as many red marbles as yours did, or more. <b>Fisher's exact test</b> does the same job for a 2 × 2 table of counts; for the one-sided version the two are the same calculation. "Exact" means no bell-curve approximation, so they work for small counts.</p>` },
    { k: 'worked', html: `<p><b>Worked example (made-up numbers).</b> An urn holds 10 marbles: 4 red, 6 blue. You scoop 3. There are 120 equally likely scoops (10 choose 3). Scoops with all 3 red: 4. So p(all red) = 4 ÷ 120 = 0.033. By luck alone you would expect 3 × 4 ÷ 10 = 1.2 red marbles.</p>` },
    { k: 'svg', caption: `The paper's overlap counts as a 2 × 2 table. Only 109, 37, 16 and 10 are printed in the paper; the cells marked * are subtraction.`,
      svg: `<svg viewBox="0 0 480 290" role="img" aria-label="A two by two table of counts for 109 positive controls. Rows: scored in A549 yes 37, no 72. Columns: scored in H460 yes 16, no 93. Cells: both 10, A549 only 27, H460 only 6, neither 66. The overlap cell of 10 is highlighted."><text x="318" y="24" class="mid b">scored in H460?</text><text x="262" y="52" class="mid s">yes</text><text x="352" y="52" class="mid s">no</text><text x="430" y="52" class="mid s">total</text><text x="92" y="116" class="end b">scored</text><text x="92" y="134" class="end b">in A549?</text><text x="128" y="96" class="end s">yes</text><text x="128" y="156" class="end s">no</text><text x="128" y="206" class="end s">total</text><rect x="222" y="64" width="80" height="50" rx="6" class="f-orange"/><text x="262" y="95" class="mid l b">10</text><rect x="312" y="64" width="80" height="50" rx="6" class="f-gray"/><text x="352" y="95" class="mid l b">27*</text><rect x="222" y="124" width="80" height="50" rx="6" class="f-gray"/><text x="262" y="155" class="mid l b">6*</text><rect x="312" y="124" width="80" height="50" rx="6" class="f-gray"/><text x="352" y="155" class="mid l b">66*</text><text x="430" y="96" class="mid b">37</text><text x="430" y="156" class="mid b">72*</text><text x="262" y="206" class="mid b">16</text><text x="352" y="206" class="mid b">93*</text><text x="430" y="206" class="mid b">109</text><text x="240" y="238" class="mid s">orange = overlap seen: 10 (by luck alone: about 5.4*)</text><text x="240" y="258" class="mid s m">* = my subtraction or arithmetic, not printed in the paper</text><text x="240" y="278" class="mid s m">Fisher / hypergeometric: how often does luck give 10 or more?</text></svg>` },
    { k: 'memory', html: `<p><b>Analogy:</b> choosing a test is choosing a tool. A <i>ruler</i> (t-test) works when measurements behave; a <i>scale that only says heavier or lighter</i> (rank test) is safer when they do not; a <i>tally of shared members</i> (hypergeometric or Fisher) is for overlap between lists. The wrong tool does not break the arithmetic, but it can give a misleading p-value.</p>` },

    { k: 'h', text: 'How this paper uses these tests' },
    { k: 'paper', ref: 'res-multipheno-p6', quote: 'out of the 109 positive controls included in the library, 37 and 16 scored in the dropout screens of A549 and H460, respectively, of which 10 are common to both (p = 0.011, hypergeometric test)' },
    { k: 'plain', source: ['res-multipheno-p6'], derived: ['5.4', '0.0115'], html: `<p>This is the marble bag. Of the 109 positive controls in the library (the marbles), 37 scored in the A549 screen (the red ones) and 16 scored in the H460 screen (the scoop). By luck you would expect about 16 × 37 ÷ 109 = 5.4 of the scoop to be red; the authors found 10. The paper reports p = 0.011 for this overlap. (My own check, not in the paper: the one-sided hypergeometric calculation for these counts gives about 0.0115, which rounds to the paper's 0.011.)</p>` },
    { k: 'paper', ref: 'fig2F', quote: 'Statistical significance: Wilcoxon test (pairwise comparisons) and Kruskal-Wallis (global differences).' },
    { k: 'plain', source: ['fig2F'], html: `<p>Figure 2F compares four groups: lncRNAs, neutral controls, and two kinds of positive control (aimed at the ORF or at the TSS). The legend uses Kruskal–Wallis for the global question and Wilcoxon for the pairwise comparisons; the panel prints "Kruskal-Wallis, P=4.2e-12" and bracket values such as 0.004 and 4.95e-05. The legend does not say why rank tests were chosen.</p>` },
    { k: 'plain', source: ['fig4F', 'fig4G', 'fig4H', 'm-cnv-p3', 'fig5G', 'fig5C', 'fig6K', 'fig3D', 'fig3F', 'fig5E', 'fig5F', 'fig6L', 'fig3C', 'fig5B'], html: `<p><b>Which test where (from the legends):</b></p><ul><li>One-tailed Welch's t test: Figure 4F (pan-hallmark hits versus non-hits in TCGA).</li><li>Pairwise two-tailed Student's t test: Figure 4G.</li><li>Fisher's exact test (one-sided): Figure 4H. The Methods say Fisher's exact tests compared hits with non-hits.</li><li>One-tailed Mann-Whitney test: Figure 5G.</li><li>Two-tailed Student's t test: Figures 5C and 6K.</li><li>One-tailed Student's t test: Figures 3D, 3F, 5E, 5F and 6L.</li><li>"Student's t test" with no direction given: Figures 3C and 5B.</li></ul>` },
    { k: 'flag', source: ['fig3D', 'fig3F', 'fig4F', 'fig4H', 'fig5E', 'fig5F', 'fig5G', 'fig6L'], html: `<p>Heads-up: many legends say "one-tailed" or "one-sided". That is a reasonable choice when only a decrease (or only an increase) was expected, but none of the legends says that the direction was fixed beforehand, or whether the Student's tests assumed equal spread. For the same data, a two-tailed p would usually be about twice as large.</p>` },
  ],
  appears: [
    { ref: 'res-multipheno-p6', note: 'The hypergeometric test for the overlap of positive controls that scored in both cell lines.' },
    { ref: 'fig2F', note: 'Kruskal–Wallis (global) and Wilcoxon (pairwise) tests on P-value distributions.' },
    { ref: 'fig4F', note: 'One-tailed Welch\'s t test for hits versus non-hits.' },
    { ref: 'fig4H', note: 'Fisher\'s exact test (one-sided) for amplifications and deletions.' },
    { ref: 'fig5G', note: 'One-tailed Mann-Whitney test.' },
    { ref: 'm-cnv-p3', note: 'Methods: Fisher\'s exact tests compare hits with non-hits.' },
  ],
  checks: [
    { q: `Why must the direction of a one-tailed test be chosen before you see the data?`,
      options: [
        { t: `Choosing it afterwards, to match the data, would halve the p-value and make "significant" too easy`, ok: true, why: `Right: picking the favorable tail after the fact quietly doubles your chance of passing the cutoff.` },
        { t: `A one-tailed test cannot be run on data that already exist`, ok: false, why: `It can be run. The problem is how the direction was chosen, not when the test is run.` },
        { t: `One-tailed tests only work with three or more groups`, ok: false, why: `One-tailed versions exist for two-group tests such as the t-test. The number of groups is not the issue.` },
        { t: `The p-value of a one-tailed test is always larger`, ok: false, why: `For an effect in the predicted direction it is smaller: half of the two-tailed value.` },
      ], bg: true },
    { q: `Skewed measurements from four groups. First you want to know whether the groups differ at all. Which test fits?`,
      options: [
        { t: `Kruskal–Wallis`, ok: true, why: `Right: a rank-based test for three or more groups gives one global answer.` },
        { t: `Welch's t-test`, ok: false, why: `A t-test compares two groups at a time and likes roughly bell-shaped data.` },
        { t: `Fisher's exact test`, ok: false, why: `That is for counts in a 2 × 2 table, not for measurements.` },
        { t: `Pearson correlation`, ok: false, why: `That measures how two measurements move together. It does not compare groups.` },
      ], bg: true },
    { q: `When is Welch's t-test the safer choice compared with Student's?`,
      options: [
        { t: `When the two groups may differ in spread or in size`, ok: true, why: `Right: Welch's test does not assume equal spread, so it stays honest in that case.` },
        { t: `When the data are counts in a 2 × 2 table`, ok: false, why: `Counts in a table call for Fisher's exact or the hypergeometric test.` },
        { t: `When there are three or more groups`, ok: false, why: `Both t-tests compare two groups.` },
        { t: `When you want a smaller p-value`, ok: false, why: `Choose a test by its assumptions, not by the p-value you hope for.` },
      ], bg: true },
    { q: `In the paper's overlap example (109 positive controls; 37 scored in A549, 16 in H460; 10 in both), about how many overlapping controls would luck alone give?`,
      options: [
        { t: `About 5.4 (16 × 37 ÷ 109)`, ok: true, why: `Right: 37 of the 109 are "red" (about a third), so about a third of the 16 scooped should be red.` },
        { t: `10, the number actually found`, ok: false, why: `That is the observed overlap. The test asks whether 10 is more than luck would give.` },
        { t: `About 8, half of 16`, ok: false, why: `Half would be right only if half of the 109 were red. Only about a third are.` },
        { t: `About 37, all the A549 scorers`, ok: false, why: `The overlap cannot exceed the shorter list (16), and luck would give far fewer.` },
      ], source: ['res-multipheno-p6'], derived: ['5.4', '8'] },
    { q: `Figure 2F reports both a Kruskal–Wallis test and Wilcoxon tests. Why both?`,
      options: [
        { t: `Kruskal–Wallis answers the global question (do the groups differ at all?); Wilcoxon compares pairs`, ok: true, why: `Right: the legend assigns them as "Wilcoxon test (pairwise comparisons) and Kruskal-Wallis (global differences)".` },
        { t: `Wilcoxon is for the lncRNAs and Kruskal–Wallis is for the controls`, ok: false, why: `The legend assigns them by type of question (global versus pairwise), not by type of group.` },
        { t: `Because the first test was not significant`, ok: false, why: `Nothing in the legend says so, and the panel prints a very small Kruskal-Wallis P (4.2e-12). The two tests answer different questions.` },
        { t: `They are two names for the same test`, ok: false, why: `Wilcoxon (rank-sum) and Mann–Whitney are two names for one test; Kruskal–Wallis is the three-or-more-groups relative.` },
      ], source: ['fig2F'] },
  ],
},

/* ============================================================================================== D11 */
{
  id: 'D11',
  body: [
    { k: 'h', text: 'A pathway is a relay; a label is a hint' },
    { k: 'bgnd', html: `<p>Lists of genes are hard to read, so biologists group genes by the job they share and give each group a name, such as "p53 pathway" or "Glycolysis". A <b>signaling pathway</b> is a relay of molecules that carries a message, for example "grow!" or "DNA is damaged!", from a sensor to a response. This lesson gives each name that appears in the paper a one-minute explanation, so that when you meet it in a figure you know the neighborhood.</p>` },

    { k: 'h', text: 'How the names reach a figure' },
    { k: 'bgnd', html: `<p>The authors lowered one lncRNA at a time, measured by RNA-seq which genes went up or down, and compared that list with collections of named gene sets (KEGG and MSigDB). A name is printed when the changed genes contain more members of a set than chance would give (enrichment). Careful: a label says "many genes of this set changed". It does not say the lncRNA acts on that pathway directly.</p><p>The MSigDB names (like "Hypoxia" or "Mitotic Spindle") look like entries of its "Hallmark" collection of about 50 curated gene sets; the paper itself says only "MSigDB". Those Hallmark sets are not the same thing as the hallmarks of cancer from lesson C1.</p>` },
    { k: 'svg', caption: 'How a pathway name ends up in a figure: from lowering a lncRNA to a printed label.',
      svg: `<svg viewBox="0 0 480 396" role="img" aria-label="Four steps. One: lower one lncRNA. Two: RNA-seq shows which genes go up or down. Three: compare that list with named gene sets such as KEGG and MSigDB. Four: sets with more matches than chance get a label such as p53 pathway. A warning says a label is a hint, not proof of a direct link."><rect x="40" y="8" width="400" height="54" rx="10" class="f-blue"/><text x="240" y="32" class="mid b">1 · Lower one lncRNA</text><text x="240" y="51" class="mid s">CHiLL1 or GCAWKR (with ASOs)</text><path d="M240 64 V84" class="arrow"/><rect x="40" y="86" width="400" height="54" rx="10" class="f-green"/><text x="240" y="110" class="mid b">2 · RNA-seq: which genes change?</text><text x="240" y="129" class="mid s">hundreds go up or down</text><path d="M240 142 V162" class="arrow"/><rect x="40" y="164" width="400" height="54" rx="10" class="f-orange"/><text x="240" y="188" class="mid b">3 · Compare with named gene sets</text><text x="240" y="207" class="mid s">KEGG pathways, MSigDB terms</text><path d="M240 220 V240" class="arrow"/><rect x="40" y="242" width="400" height="54" rx="10" class="f-purple"/><text x="240" y="266" class="mid b">4 · More matches than chance?</text><text x="240" y="285" class="mid s">then the set’s name is printed as a label</text><rect x="40" y="312" width="400" height="74" rx="10" class="f-red"/><text x="240" y="336" class="mid b">A label is a hint, not proof</text><text x="240" y="357" class="mid s">“Many genes of this set changed” does not</text><text x="240" y="375" class="mid s">mean “the lncRNA acts on it directly”</text></svg>` },

    { k: 'h', text: 'Group 1: grow and survive' },
    { k: 'bgnd', html: `<ul><li><b>MAPK pathway</b>: a relay that carries growth signals from the cell surface to the nucleus (RAS, then RAF, MEK, ERK) and tells the cell to divide. KRAS acts near the top, so this is a key route in KRAS-mutant lung cancer.</li><li><b>PI3K–Akt pathway</b>: a relay that tells the cell to survive, grow and use nutrients. It is over-active in many cancers and feeds into mTOR.</li><li><b>mTORC1 / mTOR</b>: the cell's growth controller. When nutrients and growth signals are plentiful, it switches on building and growing.</li><li><b>VEGF signaling</b>: a signal that makes blood vessels sprout, so that a tissue or a tumor gets blood supply.</li></ul>` },

    { k: 'h', text: 'Group 2: guards and alarms' },
    { k: 'bgnd', html: `<ul><li><b>p53 pathway</b>: the damage alarm. The p53 protein, a tumor suppressor, pauses the cell cycle, helps repair DNA, or triggers apoptosis when a cell is damaged or stressed. The gene for p53 is mutated in many cancers.</li><li><b>TNF-alpha signaling via NF-kB</b>: an inflammation relay. The messenger TNF-alpha makes cells switch on the transcription factor NF-kB, which turns on genes for inflammation and survival.</li><li><b>Interferon alpha response</b>: the antiviral alarm. Interferons make cells switch on defense genes, as if a virus were nearby.</li></ul>` },

    { k: 'h', text: 'Group 3: fuel, air and hormones' },
    { k: 'bgnd', html: `<ul><li><b>Glycolysis</b>: breaking down glucose (sugar) to release a little energy without needing oxygen. Many tumors use it heavily, even when oxygen is available.</li><li><b>Hypoxia</b>: low oxygen. Tumors often outgrow their blood supply, and cells answer by switching on genes for survival, glycolysis and new blood vessels (VEGF).</li><li><b>Cholesterol homeostasis</b>: how a cell keeps its cholesterol, a building block of membranes, at the right level by making, importing and exporting it.</li><li><b>Estrogen response</b>: genes that change after a cell meets the hormone estrogen ("early" and "late" refer to timing). A match shows that similar genes are moving, not that estrogen is involved.</li></ul>` },

    { k: 'h', text: 'Group 4: shape, glue and division' },
    { k: 'bgnd', html: `<ul><li><b>Epithelial–mesenchymal transition (EMT)</b>: cells in a tight sheet (epithelial) loosen their contacts and become more mobile (mesenchymal). Cancer cells can use it to move and invade, so it is linked to metastasis.</li><li><b>Apical junction</b>: the connections near the top (apical) side of sheet cells that glue neighbors together and seal the layer. Losing them goes with EMT.</li><li><b>Proteoglycans in cancer</b>: a KEGG map of sugar-coated proteins on the cell surface and between cells, and the growth-signaling and sticking partners they work with. It is a broad "surface, adhesion and growth signals" label.</li><li><b>Mitotic spindle</b>: the scaffold of protein fibers that pulls the copied chromosomes apart during mitosis, so it is a "cell division" label.</li></ul>` },
    { k: 'memory', html: `<p><b>Memory aid:</b> picture a tumor as a fast-growing town. It needs permits to build (MAPK, PI3K–Akt, mTORC1), new roads for supplies (VEGF), fuel and materials (glycolysis, cholesterol), air that sometimes runs short (hypoxia), emergency services (p53, interferon, TNF/NF-kB), and walls and gates it can open to spread out (apical junction, EMT). The mitotic spindle is how the town splits in two. Where the picture breaks down: real pathways overlap and talk to each other, and none works alone.</p>` },

    { k: 'h', text: 'How this paper uses these names' },
    { k: 'paper', ref: 'res-mechanism-p3', quote: 'These underscored disease relevance (e.g., “non-small cell lung cancer”) and also implicated potential mechanistic pathways (MAPK, PI3K-Akt)' },
    { k: 'plain', source: ['res-mechanism-p3', 'res-mechanism-p4', 'fig6F'], html: `<p><b>CHiLL1 (KEGG, Figure 6F).</b> Pathways highlighted in green as cancer-relevant and significant in both cell lines include Proteoglycans in cancer, p53 signaling pathway, PI3K-Akt signaling pathway, MAPK signaling pathway and VEGF signaling pathway (alongside Small cell lung cancer, Non-small cell lung cancer, Apoptosis and Pathways in cancer). The text calls MAPK and PI3K-Akt "potential mechanistic pathways" and adds that an MSigDB analysis implicated p53 and mTORC1 signaling (Figure S6E, a supplementary figure not reproduced here). It also notes that ZBTB7A, whose binding sites are enriched among the changing genes, has been reported to regulate processes including apoptosis and glycolysis.</p>` },
    { k: 'plain', source: ['fig6J', 'res-mechanism-p6'], html: `<p><b>GCAWKR (MSigDB, Figure 6J).</b> The bars are, from longest to shortest: p53 Pathway, Glycolysis, mTORC1 Signaling, Mitotic Spindle, Cholesterol Homeostasis, G2-M Checkpoint, Estrogen Response Early, Estrogen Response Late, Apoptosis, TNF-alpha Signaling via NF-kB, Apical Junction, Interferon Alpha Response, Hypoxia and Epithelial Mesenchymal Transition. The text says GCAWKR's terms partly overlap with CHiLL1's (including p53 pathway, cholesterol homeostasis and epithelial to mesenchymal transition), picks out "G2-M checkpoint" among the GCAWKR-specific terms, and then reports more cells in the G2 phase after GCAWKR (but not CHiLL1) knockdown (Figure 6K).</p>` },
    { k: 'plain', source: ['fig5E', 'res-aso-p6'], html: `<p><b>mTOR as a control.</b> In the spheroid experiment (Figure 5E) an ASO against mTOR is the positive control, and the text says the CHiLL1 and GCAWKR ASOs reduced viability "approaching that of the positive control, mTOR". Here mTOR is a tool, not a result: as a positive control, it is expected to lower viability.</p>` },
    { k: 'paper', ref: 'discussion-p6', quote: 'affecting hundreds of target genes that converge on many shared, oncogenic pathways, which yielded experimentally verifiable predictions' },
    { k: 'plain', source: ['discussion-p6', 'res-mechanism-p5', 'res-mechanism-p6'], html: `<p>In the Discussion the authors say that both lncRNAs affect hundreds of target genes that "converge on many shared, oncogenic pathways", and they call the results "experimentally verifiable predictions". Read the pathway names the same way: as leads. In the main text, three leads are tested directly: apoptosis (more early apoptotic cells after CHiLL1 but not GCAWKR knockdown, Figure 6G), the G2-M checkpoint (more cells in G2 after GCAWKR but not CHiLL1 knockdown, Figure 6K) and migration (impaired after GCAWKR knockdown, Figure 6L).</p>` },
    { k: 'flag', source: ['fig6J'], html: `<p>Heads-up: the legend of Figure 6J says "y axis: adjusted p value (q value)", but the bars in the picture run horizontally and the printed axis is labelled "Significance" (0 to 8). The legend does not say how that scale is calculated from the q value.</p>` },
  ],
  appears: [
    { ref: 'res-mechanism-p3', note: 'KEGG terms for CHiLL1: MAPK and PI3K-Akt called "potential mechanistic pathways".' },
    { ref: 'res-mechanism-p4', note: 'MSigDB implicates p53 and mTORC1 signaling; ZBTB7A and glycolysis.' },
    { ref: 'res-mechanism-p6', note: 'GCAWKR: p53 pathway, cholesterol homeostasis, EMT, and the G2-M checkpoint.' },
    { ref: 'fig6F', note: 'KEGG pathways for CHiLL1, with the cancer-relevant ones highlighted in green.' },
    { ref: 'fig6J', note: 'MSigDB terms for GCAWKR: Glycolysis, Hypoxia, Mitotic Spindle, Apical Junction and more.' },
    { ref: 'fig5E', note: 'An ASO against mTOR used as the positive control in spheroids.' },
  ],
  checks: [
    { q: `Figure 6J lists "Hypoxia" among the terms enriched after GCAWKR is lowered. What does that mean?`,
      options: [
        { t: `Genes of the hypoxia set are over-represented among the changed genes: a lead, not proof that GCAWKR acts through low oxygen`, ok: true, why: `Right: the paper calls such results "potential mechanistic pathways" and "predictions", not proof.` },
        { t: `The cells were short of oxygen when they were collected`, ok: false, why: `An enrichment label says the changed genes resemble a gene set. It does not measure oxygen.` },
        { t: `GCAWKR directly switches the hypoxia pathway on`, ok: false, why: `Enrichment cannot show a direct link, and a label alone does not even tell you whether those genes went up or down.` },
        { t: `All the hypoxia genes were switched off`, ok: false, why: `A set can contain genes that went up and genes that went down; the label does not say which.` },
      ], source: ['fig6J', 'res-mechanism-p3', 'discussion-p6'] },
    { q: `Which name describes the signal that makes new blood vessels sprout toward a tumor?`,
      options: [
        { t: `VEGF signaling`, ok: true, why: `Right: VEGF makes the cells that line blood vessels sprout new vessels (angiogenesis).` },
        { t: `Glycolysis`, ok: false, why: `Glycolysis is the breakdown of glucose for energy.` },
        { t: `Interferon alpha response`, ok: false, why: `That is the antiviral alarm.` },
        { t: `Mitotic spindle`, ok: false, why: `That is the machinery that pulls chromosomes apart during cell division.` },
      ], bg: true },
    { q: `A lung cancer carries an activating KRAS mutation. Which two relays does active KRAS typically keep switched on?`,
      options: [
        { t: `MAPK and PI3K–Akt`, ok: true, why: `Right: active KRAS passes signals into the RAF–MEK–ERK (MAPK) relay and into PI3K–Akt, and both push growth and survival.` },
        { t: `p53 and cholesterol homeostasis`, ok: false, why: `p53 is a damage alarm that usually works against cancer, and cholesterol homeostasis is a metabolic balance. Neither is a KRAS growth relay.` },
        { t: `Interferon alpha response and estrogen response`, ok: false, why: `These are an antiviral alarm and a hormone response, not KRAS growth relays.` },
        { t: `Apical junction and mitotic spindle`, ok: false, why: `These are about cell-to-cell glue and the cell-division machinery.` },
      ], bg: true },
    { q: `In Figure 5E, what role does the mTOR ASO play?`,
      options: [
        { t: `A positive control: it is expected to lower viability, so the CHiLL1 and GCAWKR ASOs can be compared with it`, ok: true, why: `Right: the legend calls it a positive control, and the text says the other ASOs reached a reduction "approaching that of the positive control, mTOR".` },
        { t: `A negative control that should do nothing`, ok: false, why: `A negative (non-targeting) control is a different ASO that should have no effect. The legend calls the mTOR ASO a positive control.` },
        { t: `The treatment being tested`, ok: false, why: `The treatments being tested are the CHiLL1 and GCAWKR ASOs.` },
        { t: `A housekeeping gene used to normalize the data`, ok: false, why: `Housekeeping genes normalize RNA measurements. The mTOR ASO is a treatment that lowers cell viability.` },
      ], source: ['fig5E', 'res-aso-p6'] },
    { q: `Which statement about GCAWKR follows the paper's main text?`,
      options: [
        { t: `The "G2-M checkpoint" term was singled out, and knockdown increased the share of cells in the G2 phase (not so for CHiLL1)`, ok: true, why: `Right: res-mechanism-p6 links the term to the G2-phase result in Figure 6K.` },
        { t: `The "apoptosis" term was enriched, and knockdown increased early apoptotic cells`, ok: false, why: `Figure 6J does list Apoptosis, but the assay shows more early apoptotic cells after CHiLL1 knockdown, "but not GCAWKR". A label is not a result.` },
        { t: `The p53 pathway was enriched only for CHiLL1`, ok: false, why: `The text says the p53 pathway is among the terms partly shared by the two lncRNAs.` },
        { t: `GCAWKR knockdown made cells migrate faster`, ok: false, why: `The paper reports impaired migration after GCAWKR knockdown (Figure 6L).` },
      ], source: ['res-mechanism-p5', 'res-mechanism-p6'] },
  ],
}
);
